with remaining_keys as (select location, dept_name from departments except distinct select location, dept_name from departments where dept_name is not null), verified as (select s.* from departments s inner join remaining_keys k on s.location = k.location and s.dept_name = k.dept_name) select dept_name, count(*) filter (where dept_name = 'Sales') as sales_rows, count(distinct dept_name) as distinct_dept_names, sum(case when location = 'London' then budget else 0 end) as london_budget from verified group by dept_name order by sales_rows
